#include <bits/stdc++.h>
using namespace std;
typedef __int128 i128;

// Parses one factor into exponent -> summed coefficient.
// Term: [+-]? (digits [letter]? | letter) (^ [+-]? digits)?
map<long long, long long> parse(const string &s) {
    map<long long, long long> out;
    size_t pos = 0, n = s.size();
    while (pos < n) {
        long long sign = 1;
        if (s[pos] == '+' || s[pos] == '-') { if (s[pos] == '-') sign = -1; pos++; }
        long long c = 1;
        bool hasVar = false;
        if (isdigit((unsigned char)s[pos])) {
            c = 0;
            while (pos < n && isdigit((unsigned char)s[pos])) c = c * 10 + (s[pos++] - '0');
            if (pos < n && isalpha((unsigned char)s[pos])) { hasVar = true; pos++; }
        } else {
            hasVar = true;
            pos++;
        }
        long long e = hasVar ? 1 : 0;
        if (pos < n && s[pos] == '^') {
            pos++;
            long long esign = 1;
            if (s[pos] == '+' || s[pos] == '-') { if (s[pos] == '-') esign = -1; pos++; }
            e = 0;
            while (pos < n && isdigit((unsigned char)s[pos])) e = e * 10 + (s[pos++] - '0');
            e *= esign;
        }
        out[e] += sign * c;
    }
    return out;
}

string toString(i128 v) {  // v > 0
    string s;
    while (v) { s += char('0' + (int)(v % 10)); v /= 10; }
    reverse(s.begin(), s.end());
    return s;
}

