import java.util.*;

public class Main {
    // Parses one factor into exponent -> summed coefficient.
    // Term: [+-]? (digits [letter]? | letter) (^ [+-]? digits)?
    static TreeMap<Long, Long> parse(String s) {
        TreeMap<Long, Long> out = new TreeMap<>();
        int pos = 0, n = s.length();
        while (pos < n) {
            long sign = 1;
            if (s.charAt(pos) == '+' || s.charAt(pos) == '-') {
                if (s.charAt(pos) == '-') sign = -1;
                pos++;
            }
            long c = 1;
            boolean hasVar = false;
            if (Character.isDigit(s.charAt(pos))) {
                c = 0;
                while (pos < n && Character.isDigit(s.charAt(pos))) c = c * 10 + (s.charAt(pos++) - '0');
                if (pos < n && Character.isLetter(s.charAt(pos))) {
                    hasVar = true;
                    pos++;
                }
            } else {
                hasVar = true;
                pos++;
            }
            long e = hasVar ? 1 : 0;
            if (pos < n && s.charAt(pos) == '^') {
                pos++;
                long esign = 1;
                if (s.charAt(pos) == '+' || s.charAt(pos) == '-') {
                    if (s.charAt(pos) == '-') esign = -1;
                    pos++;
                }
                e = 0;
                while (pos < n && Character.isDigit(s.charAt(pos))) e = e * 10 + (s.charAt(pos++) - '0');
                e *= esign;
            }
            out.merge(e, sign * c, Long::sum);
        }
        return out;
    }

    public static void main(String[] args) throws IOException {
        String text = new BufferedReader(new InputStreamReader(System.in)).readLine().strip();
        char letter = 'x';
        for (char ch : text.toCharArray()) if (Character.isLetter(ch)) { letter = ch; break; }
        int mid = text.indexOf(")(");
        TreeMap<Long, Long> a = parse(text.substring(1, mid)), b = parse(text.substring(mid + 2, text.length() - 1));
        // Distributive law: the coefficient of x^e is the sum of products whose exponents add to e.
        TreeMap<Long, BigInteger> product = new TreeMap<>(Collections.reverseOrder());
        for (Map.Entry<Long, Long> x : a.entrySet())
            for (Map.Entry<Long, Long> y : b.entrySet())
                product.merge(x.getKey() + y.getKey(), BigInteger.valueOf(x.getValue()).multiply(BigInteger.valueOf(y.getValue())), BigInteger::add);
        StringBuilder answer = new StringBuilder();
        for (Map.Entry<Long, BigInteger> t : product.entrySet()) {
            long e = t.getKey();
            BigInteger c = t.getValue();
            if (c.signum() == 0) continue;
            BigInteger v = c.abs();
            String body;
            if (e == 0) body = v.toString();
            else body = (v.equals(BigInteger.ONE) ? "" : v.toString()) + letter + (e == 1 ? "" : "^" + e);
            answer.append(c.signum() < 0 ? "-" : answer.length() == 0 ? "" : "+").append(body);
        }
        System.out.println(answer.length() == 0 ? "0" : answer.toString());
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"slices"
	"strings"
)

func isDigit(c byte) bool  { return c >= '0' && c <= '9' }
func isLetter(c byte) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }

// Parses one factor into exponent -> summed coefficient.
// Term: [+-]? (digits [letter]? | letter) (^ [+-]? digits)?
func parse(s string) map[int64]int64 {
	out := map[int64]int64{}
	pos, n := 0, len(s)
	for pos < n {
		sign := int64(1)
		if s[pos] == '+' || s[pos] == '-' {
			if s[pos] == '-' {
				sign = -1
			}
			pos++
		}
		c := int64(1)
		hasVar := false
		if isDigit(s[pos]) {
			c = 0
			for pos < n && isDigit(s[pos]) {
				c = c*10 + int64(s[pos]-'0')
				pos++
			}
			if pos < n && isLetter(s[pos]) {
				hasVar = true
				pos++
			}
		} else {
			hasVar = true
			pos++
		}
		e := int64(0)
		if hasVar {
			e = 1
		}
		if pos < n && s[pos] == '^' {
			pos++
			esign := int64(1)
			if s[pos] == '+' || s[pos] == '-' {
				if s[pos] == '-' {
					esign = -1
				}
				pos++
			}
			e = 0
			for pos < n && isDigit(s[pos]) {
				e = e*10 + int64(s[pos]-'0')
				pos++
			}
			e *= esign
		}
		out[e] += sign * c
	}
	return out
}

func main() {
	line, _ := bufio.NewReader(os.Stdin).ReadString('\n')
	text := strings.TrimSpace(line)
	letter := "x"
	for i := 0; i < len(text); i++ {
		if isLetter(text[i]) {
			letter = text[i : i+1]
			break
		}
	}
	mid := strings.Index(text, ")(")
	a, b := parse(text[1:mid]), parse(text[mid+2:len(text)-1])
	// Distributive law: the coefficient of x^e is the sum of products whose exponents add to e.
	product := map[int64]*big.Int{}
	term := new(big.Int)
	for e, c := range a {
		for f, d := range b {
			if product[e+f] == nil {
				product[e+f] = new(big.Int)
			}
			term.Mul(big.NewInt(c), big.NewInt(d))
			product[e+f].Add(product[e+f], term)
		}
	}
	exps := make([]int64, 0, len(product))
	for e := range product {
		exps = append(exps, e)
	}
	slices.Sort(exps)
	slices.Reverse(exps)
	var answer strings.Builder
	one := big.NewInt(1)
	for _, e := range exps {
		c := product[e]
		if c.Sign() == 0 {
			continue
		}
		v := new(big.Int).Abs(c)
		body := v.String()
		if e != 0 {
			body = ""
			if v.Cmp(one) != 0 {
				body = v.String()
			}
			body += letter
			if e != 1 {
				body += fmt.Sprintf("^%d", e)
			}
		}
		if c.Sign() < 0 {
			answer.WriteByte('-')
		} else if answer.Len() > 0 {
			answer.WriteByte('+')
		}
		answer.WriteString(body)
	}
	if answer.Len() == 0 {
		fmt.Println("0")
	} else {
		fmt.Println(answer.String())
	}
}
